    color: #333;
}

.thread-root-quote {
    padding: 12px 16px;
    background: #f8f8f8;
    border-bottom: 1px solid #e8e8e8;
    font-size: 0.9rem;
}

.thread-root-quote .msg-author {
    font-size: 0.85rem;
}

.thread-root-quote p {
    margin: 4px 0 0;
    color: #555;
    line-height: 1.4;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

/* When thread is open, the main area shrinks via flex */
.message-area.thread-open {
    flex: 0 0 55%;
}

export function scrollToBottom(element) {
    if (element) {
        element.scrollTop = element.scrollHeight;
    }
}

export function getScrollTop(element) {
    return element ? element.scrollTop : 0;
}

export function getScrollHeight(element) {
    return element ? element.scrollHeight : 0;
}

export function maintainScrollPosition(element, previousHeight) {
    if (element) {
        const newHeight = element.scrollHeight;
        element.scrollTop = newHeight - previousHeight;
    }
}

