@code {
    private const int PageSize = 30;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    // Data
    private List<Channel>? _channels;
    private Channel? _activeChannel;
    private int? _activeChannelId;
    private List<Message>? _messages;
    private Dictionary<int, ThreadSummary> _threadSummaries = new();

    // Thread panel
    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;

    // Input state
    private string _newMessageText = "";
    private string _threadReplyText = "";

    // UI state
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;
    private bool _loadingMore;
    private bool _allMessagesLoaded;

    // Element refs
    private ElementReference _messageListRef;
    private ElementReference _threadListRef;

    // JS interop
    private IJSObjectReference? _jsModule;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-e1f8e2a702fa4e85b123d767ef6abac4/Components/Pages/Chat.razor.js");
        }
    }

    // ───── Channel selection ─────

    private async Task SelectChannelAsync(Channel channel)
    {
        if (_activeChannelId == channel.Id)
            return;

        _activeChannel = channel;
        _activeChannelId = channel.Id;
        _messages = null;
        _allMessagesLoaded = false;
        _threadSummaries.Clear();
        _emojiPickerMessageId = null;

        var messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = messages;

        await ChatService.MarkChannelReadAsync(channel.Id);
        await BuildThreadSummariesAsync(messages);

        // Update the channel's unread count locally
        var idx = _channels!.FindIndex(c => c.Id == channel.Id);
        if (idx >= 0)
            _channels[idx] = channel with { UnreadCount = 0 };

        await ScrollToBottomAsync();
    }

    // ───── Pagination ─────

    private async Task OnMessageListScroll()
    {
        if (_loadingMore || _allMessagesLoaded || _messages is null || _jsModule is null)
            return;

        var scrollTop = await _jsModule.InvokeAsync<double>("getScrollTop", _messageListRef);
        if (scrollTop > 50)
            return;

        _loadingMore = true;
        StateHasChanged();

        var prevHeight = await _jsModule.InvokeAsync<double>("getScrollHeight", _messageListRef);
        var older = await ChatService.GetMessagesAsync(_activeChannelId!.Value, _messages.Count, PageSize);

        if (older.Count < PageSize)
            _allMessagesLoaded = true;

        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            await BuildThreadSummariesAsync(older);
            StateHasChanged();
            await Task.Yield();

            // Maintain scroll position after prepending
            if (_jsModule is not null)
                await _jsModule.InvokeVoidAsync("maintainScrollPosition", _messageListRef, prevHeight);
        }

        _loadingMore = false;
    }

    // ───── Sending messages ─────

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText) || _activeChannelId is null)
            return;

        var text = _newMessageText;
        _newMessageText = "";

        var sent = await ChatService.SendMessageAsync(_activeChannelId.Value, text, null);
        _messages ??= new();
        _messages.Add(sent);

        await ScrollToBottomAsync();
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    // ───── Thread panel ─────

    private async Task OpenThreadAsync(Message rootMsg)
    {
        _threadRootMessage = rootMsg;
        _threadOpen = true;
        _threadReplyText = "";
        _emojiPickerMessageId = null;

        _threadMessages = await ChatService.GetThreadAsync(rootMsg.Id);
        StateHasChanged();

        await Task.Yield();
        await ScrollThreadToBottomAsync();
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages = null;
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootMessage is null || _activeChannelId is null)
            return;

        var text = _threadReplyText;
        _threadReplyText = "";

        var reply = await ChatService.SendMessageAsync(_activeChannelId.Value, text, _threadRootMessage.Id);
        _threadMessages ??= new();
        _threadMessages.Add(reply);

        // Update thread summary
        var rootId = _threadRootMessage.Id;
        _threadSummaries[rootId] = new ThreadSummary(rootId, _threadMessages.Count, reply.SentAt);

        await ScrollThreadToBottomAsync();
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    // ───── Reactions ─────

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task AddReactionAsync(int messageId, string emoji)
    {
        _emojiPickerMessageId = null;
        await ToggleReactionAsync(messageId, emoji);
    }

    private async Task ToggleReactionAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);

        // Refresh the message in the main list
        if (_messages is not null && _activeChannelId is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(_activeChannelId.Value, 0, _messages.Count);
            _messages = refreshed;
        }

        // Also refresh thread if open
        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }
    }

    // ───── Thread summaries ─────

    private async Task BuildThreadSummariesAsync(List<Message> messages)
    {
        foreach (var msg in messages)
        {
            if (_threadSummaries.ContainsKey(msg.Id))
                continue;

            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                _threadSummaries[msg.Id] = new ThreadSummary(
                    msg.Id,
                    thread.Count,
                    thread[^1].SentAt);
            }
        }
    }

    // ───── Helpers ─────

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();

        return diff.TotalSeconds switch
        {
            < 60 => "just now",
            < 3600 => $"{(int)diff.TotalMinutes} min ago",
            < 86400 => $"{(int)diff.TotalHours}h ago",
            < 604800 => $"{(int)diff.TotalDays}d ago",
            _ => sentAt.ToString("MMM d, yyyy")
        };
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length <= 40 ? desc : desc[..37] + "…";
    }

    private async Task ScrollToBottomAsync()
    {
        await Task.Yield();
        if (_jsModule is not null)
            await _jsModule.InvokeVoidAsync("scrollToBottom", _messageListRef);
    }

    private async Task ScrollThreadToBottomAsync()
    {
        await Task.Yield();
        if (_jsModule is not null)
            await _jsModule.InvokeVoidAsync("scrollToBottom", _threadListRef);
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            await _jsModule.DisposeAsync();
        }
    }
}

